import com.google.gson.JsonElement;
import com.mojang.serialization.Codec;
import com.mojang.serialization.JsonOps;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import me.desht.pneumaticcraft.api.remote.IRemoteWidget;
import me.desht.pneumaticcraft.common.registry.ModDataComponents;
import me.desht.pneumaticcraft.lib.Log;
import net.minecraft.core.HolderLookup;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.codec.ByteBufCodecs;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.resources.RegistryOps;
import net.minecraft.world.item.ItemStack;

import java.util.Collection;
import java.util.List;
import java.util.Objects;

public class SavedRemoteLayout {
    public static final int JSON_VERSION = 2;

    public static final Codec<SavedRemoteLayout> CODEC = RecordCodecBuilder.create(builder -> builder.group(
            IRemoteWidget.CODEC.listOf().fieldOf("widgets").forGetter(s -> s.widgets)
    ).apply(builder, SavedRemoteLayout::new));

    public static final Codec<Versioned> VERSIONED_CODEC = RecordCodecBuilder.create(builder -> builder.group(
            Codec.INT.fieldOf("version").forGetter(Versioned::version),
            IRemoteWidget.CODEC.listOf().fieldOf("widgets").forGetter(Versioned::widgets)
    ).apply(builder, Versioned::new));

    public static final StreamCodec<RegistryFriendlyByteBuf, SavedRemoteLayout> STREAM_CODEC = StreamCodec.composite(
            IRemoteWidget.STREAM_CODEC.apply(ByteBufCodecs.list()), s -> s.widgets,
            SavedRemoteLayout::new
    );

    public static final SavedRemoteLayout EMPTY = new SavedRemoteLayout(List.of());

    private final List<IRemoteWidget> widgets;  // note: immutable!

    public SavedRemoteLayout(Collection<IRemoteWidget> widgets) {
        this.widgets = List.copyOf(widgets);
    }

    public static SavedRemoteLayout fromJson(HolderLookup.Provider provider, JsonElement json) {
        RegistryOps<JsonElement> ops = provider.createSerializationContext(JsonOps.INSTANCE);
        return VERSIONED_CODEC.parse(ops, json)
                .resultOrPartial(err -> Log.warning("can't parse remote layout JSON: " + err))
                .map(v -> new SavedRemoteLayout(v.widgets()))
                .orElse(EMPTY);
    }

    public JsonElement toJson(HolderLookup.Provider provider) {
        RegistryOps<JsonElement> ops = provider.createSerializationContext(JsonOps.INSTANCE);
        SavedRemoteLayout.Versioned saved = new SavedRemoteLayout.Versioned(JSON_VERSION, widgets);

        return SavedRemoteLayout.VERSIONED_CODEC.encodeStart(ops, saved).result().orElseThrow();
    }

    public static SavedRemoteLayout fromItem(ItemStack stack) {
        return stack.getOrDefault(ModDataComponents.REMOTE_LAYOUT, SavedRemoteLayout.EMPTY);
    }

    public List<IRemoteWidget> getWidgets() {
        return widgets;
    }

    @Override
    public boolean equals(Object obj) {
        if (obj == this) return true;
        if (obj == null || obj.getClass() != this.getClass()) return false;
        var that = (SavedRemoteLayout) obj;
        return Objects.equals(this.widgets, that.widgets);
    }

    @Override
    public int hashCode() {
        return Objects.hash(widgets);
    }

    @Override
    public String toString() {
        return "Saved[" + "widgets=" + widgets + ']';
    }

    public record Versioned(int version, List<IRemoteWidget> widgets) {
    }
}

package me.desht.pneumaticcraft.common.util.legacyconv;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonSyntaxException;
import me.desht.pneumaticcraft.api.lib.Names;
import me.desht.pneumaticcraft.common.remote.SavedRemoteLayout;
import me.desht.pneumaticcraft.lib.Log;

import static me.desht.pneumaticcraft.common.util.legacyconv.ConversionUtil.*;

public class ActionWidgetLegacyConv {
    public static int determineVersion(JsonObject json) {
        if (json.has("version")) {
            // 1.20.6 and newer
            return json.get("version").getAsInt();
        } else if (json.has("main")) {
            return 1;
        } else {
            throw new JsonSyntaxException("can't determine saved remote layout version!");
        }
    }

    public static void convertLegacy(JsonObject json, int oldVersion) {
        if (oldVersion == 1) {
            convertFromV1(json);
        }
    }

    private static void convertFromV1(JsonObject json) {
        JsonArray entries = json.getAsJsonObject("main").getAsJsonArray("value");

        JsonArray newDoc = new JsonArray();

        for (JsonElement entry : entries) {
            JsonObject oldEntry = entry.getAsJsonObject();

            JsonObject newEntry = new JsonObject();
            JsonObject base = new JsonObject();
            JsonObject widget = new JsonObject();

            getString(oldEntry, "enableVariable").ifPresent(val -> base.addProperty("enable_var", prefixVar(val)));
            convXYZ(oldEntry, base, "enabling", "enable_pos");

            getInt(oldEntry, "x").ifPresent(val -> widget.addProperty("x", val));
            getInt(oldEntry, "y").ifPresent(val -> widget.addProperty("y", val + 8));
            getInt(oldEntry, "width").ifPresent(val -> widget.addProperty("width", val));
            getInt(oldEntry, "height").ifPresent(val -> widget.addProperty("height", val));
            getString(oldEntry, "text").ifPresent(val -> widget.addProperty("title", val));
            getString(oldEntry, "tooltip").ifPresent(val -> widget.addProperty("tooltip", val));

            newEntry.add("base", base);
            newEntry.add("widget", widget);

            getString(oldEntry, "id").ifPresent(val -> newEntry.addProperty("type", Names.MOD_ID + ":" + val));
            getString(oldEntry, "variableName").ifPresent(val -> newEntry.addProperty("var_name", prefixVar(val)));
            convXYZ(oldEntry, newEntry, "setting", "set_pos");
            getString(oldEntry, "dropDownElements").ifPresent(val -> newEntry.addProperty("elements", val));
            getBool(oldEntry, "sorted").ifPresent(val -> newEntry.addProperty("sorted", val));

            newDoc.add(newEntry);
        }

        json.add("widgets", newDoc);
        json.remove("main");
        json.addProperty("version", SavedRemoteLayout.JSON_VERSION);

        Log.info("Pastebin Remote import (V1 -> V2): converted {} legacy widgets", newDoc.size());
    }

}

